#define PI 3.14159265358979323846

const vec2 HEXAGRAM_GRID = vec2(3.,4.);

mat2 scale(in vec2 s){ return mat2(s.x,.0,.0,s.y); }
vec2 tile (in vec2 st, in vec2 zoom) {
    st *= zoom;
    return fract(st);
}
float box(vec2 st, vec2 size){
    size = vec2(.5)-size*.5;
    vec2 uv = step(size,st) * step(size,vec2(1.)-st);
    return uv.x*uv.y;
}
float pattern(vec2 st, float o){
    st *= HEXAGRAM_GRID;
    vec2 index = floor(st);
    st = fract(st);

    float t = (iTime * 2. + o) * PI;

    if(index.x == 1.){
        if(index.y == 0.){
            return ceil(sin(1.0*t));
        } else if(index.y == 1.){
            return ceil(sin(0.5*t));
        } else if(index.y == 2.){
            return ceil(sin(0.25*t));
        } else if(index.y == 3.){
            return ceil(sin(0.125*t));
        }
    }
    return 0.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 st = fragCoord/iResolution.y;

    // make 4*4 versions
    const float CANVAS_SCALE = 4.;
    st *= CANVAS_SCALE;
    vec2 i = floor(st);
    st=fract(st);

    // padding between cells
    st -= vec2(.5);
    st = scale( vec2(1.5) ) * st;
    st += vec2(.5);
    float border = 1.-box(st,vec2(1.));
    float grid = 1.-box(tile(st,HEXAGRAM_GRID),vec2(1.,.9));

    float pattern = pattern(st, i.x+i.y*CANVAS_SCALE);
    float color = border+grid+pattern;

    fragColor = vec4(vec3(color),1.);
}
